# Chạy: python3 tools/smoke_test_app.py <duong-dan-xlsx> [thu-muc-anh]   (pip install playwright && playwright install chromium)
import sys,pathlib
from playwright.sync_api import sync_playwright
root=pathlib.Path(__file__).resolve().parent.parent
xl=sys.argv[1]; shots=pathlib.Path(sys.argv[2]) if len(sys.argv)>2 else None
if shots: shots.mkdir(exist_ok=True,parents=True)
bad=[]
def ok(c,m):
    print(("PASS ","FAIL ")[not c]+m)
    if not c: bad.append(m)
with sync_playwright() as p:
    b=p.chromium.launch();ctx=b.new_context(viewport={"width":1440,"height":900},accept_downloads=True);pg=ctx.new_page();errs=[]
    pg.on("pageerror",lambda e:errs.append(str(e)));pg.on("dialog",lambda d:d.accept())
    pg.goto((root/"index.html").as_uri());pg.wait_for_selector("#splash",state="detached")
    go=lambda n:(pg.click(f'.nav button[data-page={n}]'),pg.wait_for_timeout(350))
    shot=lambda n:shots and pg.screenshot(path=str(shots/(n+".png")))
    ok("Chào" in pg.inner_text("#greet"),"lời chào hiển thị khi chưa có dữ liệu")
    ok("Bắt đầu nhanh" in pg.inner_text("#guide"),"hướng dẫn lần đầu hiện khi chưa có dữ liệu")
    go("settings");pg.fill("#pf-name","Anh Tú");pg.press("#pf-name","Tab");pg.wait_for_timeout(300)
    ok(pg.is_disabled("#upd-check"),"nút cập nhật vô hiệu ngoài bản cài Windows")
    go("import");pg.set_input_files("#excel-file",xl);pg.wait_for_selector("#imp-go");pg.click("#imp-go");pg.wait_for_selector("#imp-body .notice:has-text('Đã nhập xong')")
    go("overview");ok("Anh Tú" in pg.inner_text("#greet"),"lời chào có tên: "+pg.inner_text("#greet"))
    ok(pg.locator("#trend svg polyline").count()==2,"biểu đồ đường 2025 và 2026")
    ok(pg.locator("#top5 .bar-track").count()==5,"Top 5 khách hàng")
    ok(pg.locator("#qchart svg rect").count()>=4 and pg.locator("#qtable tbody tr").count()==5,"biểu đồ cột và bảng theo quý");shot("quarters")
    full=pg.inner_text("#kpis");pg.select_option("#ov-region","Quảng Ninh");pg.wait_for_timeout(200)
    ok(pg.inner_text("#kpis")!=full and "4" in pg.inner_text("#kpis"),"lọc khu vực làm đổi KPI và biểu đồ")
    pg.select_option("#ov-region","");shot("overview")
    go("customers");ok(pg.locator("#customer-rows tr").count()==26,"bảng 26 dòng")
    pg.click("#cust-head [data-sort=name]");a=pg.inner_text("#customer-rows tr:first-child .cname");pg.click("#cust-head [data-sort=name]");b2=pg.inner_text("#customer-rows tr:first-child .cname")
    ok(a!=b2 and pg.get_attribute("#cust-head th.fz1","aria-sort")=="descending","sắp xếp theo tên tăng/giảm: "+a[:20]+" | "+b2[:20])
    pg.click("#cust-head [data-sort=a26]");pg.click("#cust-head [data-sort=a26]")
    pg.select_option("#col-view","q");ok(pg.locator("#cust-head th.mh").count()==0 and pg.locator("#cust-head th.nr").count()==4,"ẩn cột tháng, chỉ còn 4 quý")
    pg.select_option("#col-view","y26");ok(pg.locator("#cust-head th.mh").count()==12 and pg.locator("#cust-head th.yr").count()==12,"ẩn năm 2025: còn 12 cột 2026")
    pg.click("#col-custom");pg.uncheck("#dlg .cc-m >> nth=2");pg.click("#dlg button[type=submit]");ok(pg.locator("#cust-head th.mh").count()==11,"tuỳ chỉnh bỏ tháng 3")
    pg.select_option("#col-view","all");ok(pg.locator("#cust-head th.mh").count()==12,"trở lại tất cả cột")
    ok(pg.locator("#cust-head th").count()==22+24,"tiêu đề: 6 cột cố định + 4 quý + 12 tháng (2 hàng)")
    pg.evaluate("document.querySelector('.wide').scrollLeft=700");pg.wait_for_timeout(100)
    x=pg.evaluate("document.querySelector('#customer-rows tr td.fz1').getBoundingClientRect().left-document.querySelector('.wide').getBoundingClientRect().left")
    ok(abs(x)<2,f"cột Khách hàng vẫn cố định khi cuộn ngang (lệch {x:.0f}px)");shot("customers-scrolled")
    pg.evaluate("document.querySelector('.wide').scrollLeft=0")
    pg.fill("#customer-search","hyundai");ok(pg.locator("#customer-rows tr").count()==9,"tìm 'hyundai'");pg.click("#clear-filters")
    pg.click("#customer-rows tr:has-text('Skoda Bắc Giang')");pg.wait_for_selector("#ce-form #ce_name")
    ok("Khu vực: Bắc Giang" in pg.inner_text("#crumbs") and "Skoda Bắc Giang" in pg.inner_text("#crumbs"),"breadcrumb theo thuộc tính: "+pg.inner_text("#crumbs").replace("\n"," "))
    pg.fill("#ce_code","KH-099");pg.fill("#ce_t26","300000000")
    ok(pg.input_value("#ce_t26")=="300.000.000","ô số tiền tự định dạng 300.000.000")
    pg.click("#ce_m0_1");pg.keyboard.type("5000000");pg.fill("#ce_m1_1","3.000.000");pg.fill("#ce_m0_0","1000000")
    ok(pg.input_value("#ce_m0_1")=="5.000.000","gõ từng số vẫn tự chèn dấu chấm")
    pg.click("#ce-recalc");ok(pg.input_value("#ce_a26")=="8.000.000" and pg.input_value("#ce_q0")=="8.000.000" and pg.input_value("#ce_a25")=="1.000.000","tính lại quý và tổng từ tháng")
    ok(pg.inner_text("#sum26").strip()=="8.000.000","dòng tổng 2026 cập nhật trực tiếp")
    shot("edit-page");pg.click("#ce-form button[type=submit]");pg.wait_for_selector("#customer-rows tr:has-text('KH-099')")
    row=pg.inner_text("#customer-rows tr:has-text('KH-099')");ok("5,0 tr" in row and "3,0 tr" in row and "8,0 tr" in row and "300 triệu" in row,"lưu xong về danh sách, số liệu hiển thị: "+row.replace("\n"," ")[:80])
    pg.click("#customer-rows tr:has-text('KH-099')");pg.fill("#ce_note","x");pg.click('#crumbs [data-crumb=customers]');ok(pg.is_visible("#customer-rows"),"rời trang có thay đổi chưa lưu: hộp thoại xác nhận được chấp nhận")
    pg.click("#customer-rows tr:has-text('KH-099')");pg.click("#ce-arch");pg.wait_for_selector("#customer-rows tr:has-text('KH-099')",state="detached");ok(True,"lưu trữ ngay trong trang sửa")
    pg.click("#toast .btn");pg.wait_for_selector("#customer-rows tr:has-text('KH-099')");ok(True,"Hoàn tác việc lưu trữ")
    pg.click("#customer-rows tr:has-text('KH-099')");pg.click("#ce-arch");pg.wait_for_selector("#customer-rows tr:has-text('KH-099')",state="detached")
    pg.click("#add-customer");pg.click("#ce-form button[type=submit]");ok("Hãy nhập tên" in pg.inner_text("#err_ce_name") and pg.get_attribute("#ce_name","aria-invalid")=="true","lỗi hiện ngay dưới ô tên (có aria-invalid)");pg.click("#ce-cancel")
    pg.click("#add-customer");pg.fill("#ce_name","Khách thử nghiệm");pg.fill("#ce_t26","1000");pg.click("#ce-form button[type=submit]");pg.wait_for_selector("#customer-rows tr:has-text('Khách thử nghiệm')");ok(True,"thêm khách hàng mới bằng trang con")
    pg.evaluate("document.querySelector('.wide').scrollLeft=900");pg.wait_for_timeout(100)
    al=pg.evaluate("""(()=>{const h=[...document.querySelectorAll('#cust-head tr:nth-child(2) th')].find(t=>t.getBoundingClientRect().right>700&&t.getBoundingClientRect().left>650),i=[...document.querySelectorAll('#cust-head tr:nth-child(2) th')].indexOf(h);const c=document.querySelector('#customer-rows tr td.m0');return [Math.round(h.getBoundingClientRect().right),Math.round(c.getBoundingClientRect().right),i]})()""")
    shot("grid")
    go("calendar");pg.click("#add-work");pg.click("#dlg-form button.primary");ok("Hãy nhập nội dung" in pg.inner_text("#err_f_title"),"lỗi ngay dưới ô nội dung công việc");pg.fill("#f_title","Thăm Kia Bắc Ninh");pg.click("#dlg-form button.primary");pg.wait_for_selector(".task:has-text('Thăm Kia Bắc Ninh')");ok(True,"thêm công việc")
    pg.click("#toast .btn");pg.wait_for_selector(".task:has-text('Thăm Kia Bắc Ninh')",state="detached");ok(True,"Hoàn tác việc thêm công việc")
    pg.click("#add-work");pg.fill("#f_title","Thăm Kia Bắc Ninh");pg.click("#dlg-form button.primary");pg.wait_for_selector(".task:has-text('Thăm Kia Bắc Ninh')")
    ok(pg.locator("#week-grid .day-card").count()>=6 and "THỨ BẢY" in pg.inner_text("#week-grid"),"lịch hiển thị từ thứ 2 đến thứ 7")
    pg.click("#month-stats");pg.wait_for_selector("#dlg .stbl");t=pg.inner_text("#dlg");ok("Theo loại công việc" in t and "Theo tuần" in t and "Tỉ lệ hoàn thành" in t,"bảng thống kê tháng");shot("stats")
    pg.click("#st-prev");pg.wait_for_selector("#dlg .notice");ok(True,"chuyển sang tháng trước (tháng trống)");pg.keyboard.press("Escape")
    pg.keyboard.press("Alt+2");pg.wait_for_timeout(300);ok(pg.is_visible("#customer-rows"),"Alt+2 mở Khách hàng")
    pg.keyboard.press("Control+k");ok(pg.evaluate("document.activeElement.id")=="customer-search","Ctrl+K đưa con trỏ vào ô tìm kiếm")
    pg.keyboard.press("Escape");pg.click("body",position={"x":700,"y":20});pg.keyboard.press("?");pg.wait_for_selector("#dlg:has-text('Phím tắt')");ok(True,"phím ? mở bảng phím tắt");pg.keyboard.press("Escape")
    go("settings");pg.click("#settings-theme");ok(pg.evaluate("document.documentElement.dataset.theme")=="dark","giao diện tối")
    with pg.expect_download() as d: pg.click("#bk-export")
    f=d.value.path();pg.click("#wipe");pg.wait_for_function("document.querySelector('#set-data').textContent.startsWith('0 khách')")
    pg.set_input_files("#bk-file",f);pg.wait_for_function("document.querySelector('#set-data').textContent.startsWith('27 khách')");ok(True,"xóa rồi khôi phục từ sao lưu")
    go("overview");ok("Anh Tú" in pg.inner_text("#greet"),"tên hiển thị được khôi phục");shot("overview-dark")
    pg.reload();pg.wait_for_selector("#splash",state="detached");go("customers");ok(pg.locator("#customer-rows tr").count()==26,"dữ liệu còn sau khi mở lại")
    ok(not errs,"không có lỗi JavaScript "+str(errs));b.close()
print("KẾT QUẢ:", "ĐẠT" if not bad else "CÓ LỖI: "+"; ".join(bad))
